/// Repo-relative location of the build-readable store. Deliberately OUTSIDE `src-tauri/data`, which is
/// embedded into the binaries and shipped.
pub const REPO_STORE_REL: &str = "graph/algorithms.json";

/// Read the repo store at `path` WITHOUT the seed reconcile — the store file MERGED with the
/// per-record files beside it.
///
/// Returns `Ok(None)` when the file is absent — a repo that has migrated nothing yet is not an error,
/// and a build script must be able to tell "nothing to materialize" from "the store is corrupt".
///
/// # It merges `graph/records/*.json`, and that is not optional
///
/// The store is being taken apart into one file per record
/// (`epic-retire-json-ledgers-for-db-and-git-drivers`): a 27 MB single file means every branch that
/// touches any record conflicts with every other, which is the whole reason a decomposition wave
/// costs a night of hand-merging. Records live under `graph/records/<id>.json`, mirroring
/// `src-tauri/data/components/**`, where a record has always been one file.
///
/// The merge is DELEGATED to [`graph_materialize::load_merged_value`] rather than re-implemented,
/// because the materializer is what the BUILD reads: two implementations of "which records exist"
/// that can disagree is precisely the failure the split is meant to remove. A reader that parses the
/// store file alone sees an `implementations` array missing every split-out record and says nothing
/// about it.
pub fn read_at(path: &Path) -> Result<Option<Value>, String> {
    graph_materialize::load_merged_value(path)
}

/// Write the repo store at `path`, splitting `implementations` back out into `records/<id>.json`.
///
/// The inverse of [`read_at`], and it must be, or a read-modify-write collapses every split record
/// back into the monolith the split exists to retire. Every write to the committed store goes
/// through here for that reason.
///
/// # The layout is chosen by the DESTINATION, never by a flag
///
/// If a `records/` directory sits beside `path`, that store is in the per-record layout and every
/// implementation is written as its own file, leaving the store file carrying only the document's
/// other keys (`version`, `note`, `edges`) and an empty `implementations` array. If there is no such
/// directory — the PACKAGED SEED at `src-tauri/data/knowledge/algorithms.json`, and every temp store
/// a test writes — the whole document is written as one file exactly as before.
///
/// That rule is what makes this safe to call from `promote`, which writes the repo store on one path
/// and the packaged seed on another: the seed ships inside the binaries via `include_dir!` and is a
/// single file by design.
///
/// # A record that disappeared is DELETED, not left behind
///
/// `impl remove --repo` and `impl decompose` both drop ids from the array. A stale
/// `records/<id>.json` would be silently merged back in by the next [`read_at`] — the record would
/// come back from the dead — so any record file whose id is no longer in the document is removed.
/// Files are rewritten only when their bytes actually change, so a promote of one record does not
/// restat 1,700 files into a diff.
pub fn write_at(path: &Path, store: &Value) -> Result<(), String> {
    let Some(dir) = graph_materialize::records_dir_beside(path) else {
        return write_whole(path, store);
    };
    if !dir.is_dir() {
        return write_whole(path, store);
    }

    let mut split = store.clone();
    let impls: Vec<Value> = split
        .get_mut("implementations")
        .and_then(|v| v.as_array_mut())
        .map(std::mem::take)
        .unwrap_or_default();

    let mut kept: std::collections::BTreeSet<String> = Default::default();
    for rec in &impls {
        let id = rec.get("id").and_then(Value::as_str).ok_or_else(|| {
            format!("a record in {} has no `id`, so it has no file to live in: {rec}", path.display())
        })?;
        kept.insert(id.to_string());
        let body = serde_json::to_string_pretty(rec)
            .map_err(|e| format!("cannot render the record '{id}': {e}"))? + "\n";
        let file = dir.join(format!("{id}.json"));
        if std::fs::read_to_string(&file).ok().as_deref() != Some(body.as_str()) {
            std::fs::write(&file, &body)
                .map_err(|e| format!("cannot write {}: {e}", file.display()))?;
        }
    }

    for p in record_files(&dir) {
        let stem = p.file_name().and_then(|s| s.to_str()).unwrap_or_default();
        let id = stem.strip_suffix(".json").unwrap_or(stem);
        if !kept.contains(id) {
            std::fs::remove_file(&p).map_err(|e| format!("cannot remove {}: {e}", p.display()))?;
        }
    }

    // The store file keeps the document's OTHER keys and an empty array rather than dropping the key:
    // `implementations` absent and `implementations` empty are the same fact, and every reader already
    // handles the empty one.
    if let Some(list) = split.get_mut("implementations").and_then(|v| v.as_array_mut()) {
        list.clear();
    }
    write_whole(path, &split)
}

/// The per-record files under `dir`, sorted — `[]` when there is no such directory.
///
/// Sorted because the merged `implementations` array must be deterministic: two machines reading the
/// same checkout have to agree on record ORDER, or every id-keyed diff of the store is noise.
pub fn record_files(dir: &Path) -> Vec<PathBuf> {
    let Ok(entries) = std::fs::read_dir(dir) else { return Vec::new() };
    let mut files: Vec<PathBuf> = entries
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().and_then(|s| s.to_str()) == Some("json"))
        .collect();
    files.sort();
    files
}

/// One JSON document to one file, in the store's committed format — pretty, two-space, one trailing
/// newline. The shape `serde_json::to_string_pretty` produces is what the committed file already is,
/// verified by round-tripping it byte for byte.
fn write_whole(path: &Path, doc: &Value) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
    }
    let body = serde_json::to_string_pretty(doc)
        .map_err(|e| format!("cannot render {}: {e}", path.display()))?;
    std::fs::write(path, format!("{body}\n"))
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}

/// The fields a `GraphEdge` declares — see `crate::GraphEdge`.
///
/// An edge is projected through its OWN field list and never through [`seed_content_of`]: that one
/// keeps [`SEED_FIELDS`], which has no `members`, so projecting an edge through it silently produces
/// an edge that spans nothing. That is worse than refusing, because `set_edge`'s two-member rule only
/// guards the WRITE and a store loaded from such a file would read as a covered relationship over an
/// empty member list.
pub const EDGE_FIELDS: &[&str] = &["id", "members", "src", "tests"];

/// One id's promotion verdict — what `promote` did, or what `--check` found.
#[derive(Debug, PartialEq, Eq)]
pub enum Verdict {
    /// The repo store already matches the runtime store.
    UpToDate,
    /// The record differs (or is absent from the repo store) and would be written.
    Differs,
    /// The runtime store has no such id — nothing to promote from.
    MissingUpstream,
    /// The runtime record is a SUBSET of the committed one: same code, but missing fields the committed
    /// copy carries. Promoting would DELETE those fields, so this is reported and never written.
    ///
    /// This is not hypothetical. On 2026-08-20 the running app rewrote the per-user runtime store from
    /// 969 implementations to 726, stripping `domain`, `folder`, `kind`, `vizCode`, `src` and `tests`
    /// from records the repo store had already captured. `--check` called that "the repo store is out of
    /// date — run promote", and following its own advice would have destroyed the richer committed copy.
    /// A check that cannot tell which side regressed must not assert a direction.
    RuntimeBehind,
}


/// Every field the packaged impl seed actually carries, in the order it reads best.
///
/// Derived from the shipped records rather than hand-maintained — the list this replaces had drifted
/// to omit `kind`, `summary`, `tests` and `vizCode`, so promoting over an existing entry silently
/// dropped whichever of those it had.
///
/// THAT DRIFT RECURRED, and the second time it did not fail silently — it failed CLOSED. `feature` is
/// on all 670 packaged records and was absent here, so [`seed_content_of`] projected it away and the
/// promote refused every single record rather than lose it. `bsc graph promote --seed` was inert for
/// the whole seed, which is the safe direction and still a defect. The comment claiming this list was
/// derived was the problem: it was WRITTEN by hand from a derivation done once, so
/// `seed_fields_covers_every_field_the_packaged_seed_carries` now derives it on every run.
pub const SEED_FIELDS: &[&str] = &[
    "id", "tech", "name", "role", "domain", "feature", "folder", "src", "provides", "composes",
    "kind", "summary", "ref", "tests", "code", "vizCode",
];

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn the_seed_projection_keeps_every_field_the_seed_actually_ships() {
        // The list this replaces had drifted to omit `kind`, `summary`, `tests` and `vizCode`, so
        // promoting over an existing entry silently dropped whichever of those it had.
        let rec = json!({
            "id": "x", "tech": "typescript", "name": "X", "role": "algorithm", "code": "1",
            "kind": "sort", "summary": "s", "tests": ["t"], "vizCode": "v", "ref": "r",
            "domain": "d", "folder": "f", "src": "s.ts", "provides": "@/x", "composes": ["y"],
        });
        let got = seed_content_of(&rec);
        for k in ["kind", "summary", "tests", "vizCode", "ref"] {
            assert!(got.get(k).is_some(), "{k} was dropped by the seed projection");
        }
    }

    #[test]
    fn the_seed_projection_drops_provenance_and_harvest_metadata() {
        let rec = json!({
            "id": "x", "code": "1", "rev": 3, "updatedAt": "now", "updatedBy": "me",
            "history": [1], "build": {}, "moduleAttrs": ["#[cfg(x)]"], "moduleVis": "pub",
        });
        let got = seed_content_of(&rec);
        for k in ["rev", "updatedAt", "updatedBy", "history", "build", "moduleAttrs", "moduleVis"] {
            assert!(got.get(k).is_none(), "{k} leaked into the seed");
        }
    }

    #[test]
    fn a_file_extension_in_the_tech_field_is_normalised() {
        // `extract.rs` maps the EXTENSION `ts` to the TECH `typescript`; the packaged seed is uniformly
        // `typescript`/`rust`. One stray `ts` drops that record out of its technology tab silently.
        assert_eq!(seed_content_of(&json!({"id":"a","tech":"ts"})).get("tech").unwrap(), "typescript");
        assert_eq!(seed_content_of(&json!({"id":"a","tech":"rs"})).get("tech").unwrap(), "rust");
        assert_eq!(seed_content_of(&json!({"id":"a","tech":"rust"})).get("tech").unwrap(), "rust");
    }

    /// A DECOMPOSED target is REPOINTED, not dropped. `extract` rewrites `X.rs` into `X--mod.rs` plus
    /// one child per leaf, so an edge pointing at `X.rs` still has a target and is as real as it ever
    /// was — dropping it deletes a relationship the graph holds.
    ///
    /// MEASURED on the first extraction run: of 19 records repaired, 17 already carried BOTH forms
    /// (so a drop was harmless and this went unnoticed) and 2 carried only the flat id and lost the
    /// edge. The fixture is that second shape deliberately.
    #[test]
    fn a_decomposed_composes_target_is_repointed_at_its_mod_parent() {
        let mut store = json!({ "implementations": [
            { "id": "a--mod.rs", "name": "a" },
            { "id": "a--leaf.rs", "name": "leaf" },
            { "id": "b.rs", "name": "b", "composes": ["a.rs", "gone-for-good.rs"] },
        ]});
        let dropped = prune_dangling_composes(&mut store);
        let b = impls_of(&store).into_iter().find(|r| r["id"] == "b.rs").unwrap();
        let composes: Vec<&str> =
            b["composes"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
        assert_eq!(composes, vec!["a--mod.rs"], "the decomposed edge follows its parent");
        assert_eq!(
            dropped,
            vec![("b.rs".to_string(), vec!["gone-for-good.rs".to_string()])],
            "and only a target with NO successor is reported dropped"
        );
    }

    /// It must not DUPLICATE the parent when the record already carries both forms — the common shape,
    /// and the one that hid the bug above.
    #[test]
    fn repointing_does_not_duplicate_a_parent_already_composed() {
        let mut store = json!({ "implementations": [
            { "id": "a--mod.rs", "name": "a" },
            { "id": "b.rs", "name": "b", "composes": ["a--mod.rs", "a.rs"] },
        ]});
        prune_dangling_composes(&mut store);
        let b = impls_of(&store).into_iter().find(|r| r["id"] == "b.rs").unwrap();
        assert_eq!(b["composes"].as_array().unwrap().len(), 1, "one edge, not two: {}", b["composes"]);
    }

    #[test]
    fn a_dangling_composes_target_is_pruned_and_reported() {
        let mut store = json!({"implementations": [
            {"id": "a", "composes": ["b", "not-an-impl"]},
            {"id": "b", "composes": []},
        ]});
        let dropped = prune_dangling_composes(&mut store);
        assert_eq!(dropped, vec![("a".to_string(), vec!["not-an-impl".to_string()])]);
        assert_eq!(impls_of(&store)[0].get("composes").unwrap(), &json!(["b"]));
    }

    #[test]
    fn a_promotion_that_would_orphan_a_live_specifier_is_refused() {
        // The real case: six impls still say `@/features/planner/fleet/…` after those modules moved to
        // `@/features/glance/fleet/…`. Both values are authored and `src` is stale on both sides, so it
        // is only decidable in aggregate — something still imports the specifier the promote drops.
        let before = json!({"implementations": [{"id": "m", "provides": "@/features/glance/fleet/W"}]});
        let mut next = json!({"implementations": [{"id": "m", "provides": "@/features/planner/fleet/W"}]});
        let imported = ["@/features/glance/fleet/W".to_string()].into_iter().collect();
        let reverted = refuse_orphaning_promotions(&before, &mut next, &imported);
        assert_eq!(reverted, vec![("m".to_string(), "@/features/glance/fleet/W".to_string())]);
        assert_eq!(
            impls_of(&next)[0].get("provides").unwrap(),
            "@/features/glance/fleet/W",
            "the record was not restored to the specifier its importers still name"
        );
    }

    #[test]
    fn a_specifier_nothing_imports_may_still_be_repointed() {
        // The guard is "do not BREAK resolution", not "never change" — an unreferenced specifier is the
        // author's to move.
        let before = json!({"implementations": [{"id": "m", "provides": "@/old"}]});
        let mut next = json!({"implementations": [{"id": "m", "provides": "@/new"}]});
        let reverted = refuse_orphaning_promotions(&before, &mut next, &Default::default());
        assert!(reverted.is_empty());
        assert_eq!(impls_of(&next)[0].get("provides").unwrap(), "@/new");
    }

    #[test]
    fn quoted_specifiers_finds_what_names_a_module() {
        let mut got = std::collections::BTreeSet::new();
        quoted_specifiers("import { a } from \"@/x/y\";\nconst b = '@/z';", &mut got);
        assert!(got.contains("@/x/y"), "{got:?}");
        assert!(got.contains("@/z"), "{got:?}");
    }

    #[test]
    fn the_seed_path_is_not_the_repo_store_path() {
        // Different targets on purpose: one is what the BUILD compiles, the other is what SHIPS.
        let r = Path::new("/repo");
        assert_ne!(seed_path_under(r), path_under(r));
        assert!(seed_path_under(r).ends_with("src-tauri/data/knowledge/algorithms.json"));
    }


    fn rec(id: &str, code: &str) -> Value {
        json!({ "id": id, "role": "algorithm", "tech": "rust", "code": code })
    }

    /// A scratch repo store whose directory is unique per test — every one of these writes files, so a
    /// shared directory would make them race under `cargo test` (threads in one process) while passing
    /// under `cargo nextest` (one process each), which is the exact isolation trap this repo has paid
    /// for twice.
    fn scratch(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "bsc-repo-store-split-{tag}-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("graph")).expect("scratch repo");
        dir
    }

    /// The whole point of the split: a record that lives in `graph/records/<id>.json` is part of the
    /// store every reader sees, not a second store nobody merges.
    #[test]
    fn a_per_record_file_is_merged_into_the_store_on_read() {
        let root = scratch("read");
        let store = path_under(&root);
        std::fs::write(&store, r#"{"version":1,"implementations":[{"id":"in-file.rs","code":"a"}]}"#)
            .unwrap();
        assert_eq!(impls_of(&read_at(&store).unwrap().unwrap()).len(), 1, "no records/ dir is a no-op");

        std::fs::create_dir_all(root.join("graph").join("records")).unwrap();
        std::fs::write(
            root.join("graph").join("records").join("split-out.rs.json"),
            r#"{"id":"split-out.rs","code":"b"}"#,
        )
        .unwrap();

        let merged = read_at(&store).unwrap().unwrap();
        let merged_impls = impls_of(&merged);
        let ids: Vec<&str> =
            merged_impls.iter().filter_map(|r| r.get("id").and_then(Value::as_str)).collect();
        assert_eq!(
            ids,
            vec!["in-file.rs", "split-out.rs"],
            "a reader that parses the store file alone misses every split-out record and says nothing"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    /// `write_at` is the INVERSE of `read_at`, and it has to be: a read-modify-write that wrote the
    /// whole document back would collapse every split record into the monolith the split retires.
    #[test]
    fn a_write_splits_records_back_out_and_the_round_trip_is_stable() {
        let root = scratch("write");
        let store = path_under(&root);
        let records = root.join("graph").join("records");
        std::fs::create_dir_all(&records).unwrap();
        std::fs::write(&store, r#"{"version":1,"implementations":[]}"#).unwrap();

        let doc = json!({
            "version": 1,
            "note": "kept",
            "edges": [{ "id": "e" }],
            "implementations": [rec("a.rs", "fn a() {}"), rec("b.rs", "fn b() {}")],
        });
        write_at(&store, &doc).unwrap();

        // The store FILE keeps everything but the records.
        let on_disk: Value =
            serde_json::from_str(&std::fs::read_to_string(&store).unwrap()).unwrap();
        assert!(impls_of(&on_disk).is_empty(), "the monolith keeps no implementations: {on_disk}");
        assert_eq!(on_disk.get("note").unwrap(), "kept", "the document's other keys survive");
        assert_eq!(on_disk.get("edges").unwrap().as_array().unwrap().len(), 1);
        assert!(records.join("a.rs.json").is_file(), "each record got its own file");
        assert!(records.join("b.rs.json").is_file());

        // And reading it back gives the document we wrote.
        let back = read_at(&store).unwrap().unwrap();
        assert_eq!(impls_of(&back), impls_of(&doc), "read(write(x)) == x for the records");
        assert_eq!(back.get("note").unwrap(), "kept");
        let _ = std::fs::remove_dir_all(&root);
    }

    /// A record dropped from the document must lose its FILE too. Leaving it behind would have the next
    /// `read_at` merge it straight back in — the record returning from the dead, silently, which is
    /// exactly what `impl remove --repo` and `impl decompose` must not do.
    #[test]
    fn a_record_removed_from_the_document_loses_its_file() {
        let root = scratch("remove");
        let store = path_under(&root);
        let records = root.join("graph").join("records");
        std::fs::create_dir_all(&records).unwrap();
        std::fs::write(&store, r#"{"implementations":[]}"#).unwrap();

        write_at(&store, &json!({ "implementations": [rec("a.rs", "1"), rec("b.rs", "2")] })).unwrap();
        write_at(&store, &json!({ "implementations": [rec("a.rs", "1")] })).unwrap();

        assert!(records.join("a.rs.json").is_file());
        assert!(!records.join("b.rs.json").exists(), "the dropped record's file must go with it");
        assert_eq!(impls_of(&read_at(&store).unwrap().unwrap()).len(), 1);
        let _ = std::fs::remove_dir_all(&root);
    }

    /// The layout is chosen by the DESTINATION, never by a flag — which is what lets `promote` call one
    /// writer for the repo store and for the packaged seed. The seed ships inside the binaries via
    /// `include_dir!` and is one file by design; splitting it would change what the app loads.
    #[test]
    fn a_store_with_no_records_dir_is_written_whole() {
        let root = scratch("whole");
        let seed = root.join("seed.json");
        write_at(&seed, &json!({ "implementations": [rec("a.rs", "1")] })).unwrap();
        let on_disk: Value = serde_json::from_str(&std::fs::read_to_string(&seed).unwrap()).unwrap();
        assert_eq!(impls_of(&on_disk).len(), 1, "no records/ beside it ⇒ one file, as before");
        assert!(!root.join("records").exists(), "and no directory is invented");
        let _ = std::fs::remove_dir_all(&root);
    }

    /// The committed format, pinned: two-space pretty JSON with ONE trailing newline. Not cosmetic —
    /// the per-record files are what git diffs and merges, so a writer that disagreed with the split
    /// would rewrite all 1,700 of them the first time a promote ran.
    #[test]
    fn a_record_file_is_two_space_pretty_json_with_a_trailing_newline() {
