    /// `SEED_FIELDS` must COVER every field the packaged seed actually carries — derived on every run,
    /// not written down once and called derived.
    ///
    /// A field the seed has and this list lacks is projected away by [`seed_content_of`], and
    /// `promote --seed` then refuses the record rather than lose it. MEASURED 2026-09-01: `feature` was
    /// on all 670 packaged records and absent from the list, so the verb refused EVERY one of them —
    /// `bsc graph promote --seed` was inert for the entire seed. That is the safe direction of the
    /// failure and still a defect, and it is the SECOND time this list has drifted (the first dropped
    /// `kind`, `summary`, `tests` and `vizCode`, which failed silently instead).
    ///
    /// Coverage, deliberately, not equality: a field in `SEED_FIELDS` that no record happens to carry
    /// yet is fine — `vizCode` is optional and rare — but a field on a record that the list does not
    /// name is a promotion that cannot happen.
    #[test]
    fn seed_fields_covers_every_field_the_packaged_seed_carries() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .expect("crate is nested two levels under the repo root")
            .to_path_buf();
        let seed = root.join("src-tauri").join("data").join("knowledge").join("algorithms.json");
        let Ok(text) = std::fs::read_to_string(&seed) else { return };
        let Ok(doc) = serde_json::from_str::<Value>(&text) else { return };
        let records = doc.get("implementations").and_then(Value::as_array).cloned().unwrap_or_default();
        assert!(!records.is_empty(), "the packaged seed carries records");

        let known: std::collections::BTreeSet<&str> = SEED_FIELDS.iter().copied().collect();
        let mut missing: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
        for rec in &records {
            let Some(obj) = rec.as_object() else { continue };
            for key in obj.keys() {
                if !known.contains(key.as_str()) {
                    *missing.entry(key.clone()).or_default() += 1;
                }
            }
        }
        assert!(
            missing.is_empty(),
            "the packaged seed carries {} field(s) SEED_FIELDS does not name, so `promote --seed` \
             REFUSES every record that has one rather than dropping it:\n{}\n\nAdd them to \
             SEED_FIELDS (and say in its doc comment what drifted).",
            missing.len(),
            missing
                .iter()
                .map(|(k, n)| format!("  {k} — on {n} of {} records", records.len()))
                .collect::<Vec<_>>()
                .join("\n"),
        );
    }

    /// The committed store must parse and be readable WITHOUT a home dir, an env var, or the runtime
    /// store — that is the whole point of it existing. A fresh clone and a CI checkout have none of
    /// those, and if this guard ever fails the build's source of truth is unreadable there.
    #[test]
    fn the_committed_repo_store_parses_and_needs_nothing_but_the_repo() {
        // Walk up from this file to the repo root (crates/bsc-graph/src -> ../../..).
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .expect("crate is nested two levels under the repo root")
            .to_path_buf();
        let path = path_under(&root);
        let store = read_at(&path).expect("the committed store must parse");
        let Some(store) = store else {
            // Absent is legitimate before anything is migrated; nothing further to assert.
            return;
        };
        assert!(
            store.get("implementations").and_then(Value::as_array).is_some(),
            "the committed store carries an implementations array"
        );
        for rec in impls_of(&store) {
            assert!(rec.get("id").and_then(Value::as_str).is_some(), "every record has an id: {rec}");
            assert!(
                rec.get("history").is_none() && rec.get("rev").is_none(),
                "write bookkeeping must never be committed — it churns the file on every write: {rec}"
            );
        }
    }

    #[test]
    fn the_repo_store_path_is_outside_the_packaged_seed_that_ships() {
        let p = path_under(Path::new("/repo"));
        let s = p.to_string_lossy().replace('\\', "/");
        assert!(s.ends_with("graph/algorithms.json"), "{s}");
        assert!(!s.contains("src-tauri/data"), "must not live in the SHIPPED seed: {s}");
    }

    /// THE REGRESSION THIS EXISTS FOR. On 2026-08-20 the running app rewrote the runtime store from 969
    /// implementations to 726, stripping `domain`/`folder`/`kind`/`vizCode`/`src`/`tests` while leaving
    /// `code` byte-identical. The check called it "the repo store is out of date — run promote", and
    /// obeying that would have deleted the richer committed copy.
    #[test]
    fn a_regressed_runtime_record_is_reported_behind_rather_than_drifted() {
        let rich = json!({ "id": "x.rs", "code": "fn x() {}", "vizCode": "({})", "domain": "sorting" });
        let thin = json!({ "id": "x.rs", "code": "fn x() {}" });
        assert_eq!(
            verdict_for(std::slice::from_ref(&thin), std::slice::from_ref(&rich), "x.rs"),
            Verdict::RuntimeBehind,
            "same code, fewer fields — the runtime regressed, the repo did not go stale"
        );
        // The other direction is still real drift: the runtime has something the repo lacks.
        assert_eq!(
            verdict_for(std::slice::from_ref(&rich), std::slice::from_ref(&thin), "x.rs"),
            Verdict::Differs
        );
    }

    #[test]
    fn promote_refuses_to_write_a_record_that_would_lose_fields() {
        let rich = json!({ "id": "x.rs", "code": "fn x() {}", "vizCode": "({})" });
        let thin = json!({ "id": "x.rs", "code": "fn x() {}" });
        let repo = json!({ "version": 1, "implementations": [rich] });
        let (out, missing, refused) = promote_into(&repo, std::slice::from_ref(&thin), &["x.rs".to_string()]);
        assert!(missing.is_empty());
        assert_eq!(refused, vec!["x.rs".to_string()], "refused rather than silently stripping");
        assert!(impls_of(&out)[0].get("vizCode").is_some(), "the field survived");
    }

    /// A genuine edit must still get through — the guard must not freeze the store.
    #[test]
    fn promote_still_writes_a_real_change() {
        let repo = json!({ "version": 1, "implementations": [json!({ "id": "x.rs", "code": "old" })] });
        let up = json!({ "id": "x.rs", "code": "new" });
        let (out, _, refused) = promote_into(&repo, std::slice::from_ref(&up), &["x.rs".to_string()]);
        assert!(refused.is_empty());
        assert_eq!(impls_of(&out)[0]["code"], json!("new"));
    }

    #[test]
    fn loss_is_about_key_presence_not_value_equality() {
        assert!(loses_fields(&json!({ "a": 1 }), &json!({ "a": 1, "b": 2 })), "b would be dropped");
        assert!(!loses_fields(&json!({ "a": 1, "b": 9 }), &json!({ "a": 1, "b": 2 })), "b changes, nothing lost");
        assert!(!loses_fields(&json!({ "a": 1 }), &json!({ "a": 1 })));
        // An empty value is nothing to lose.
        assert!(!loses_fields(&json!({ "a": 1 }), &json!({ "a": 1, "b": "" })));
    }

    /// The 3 records the first (subset-based) rule missed: they lost fields AND had a summary rewritten,
    /// so they were not a clean subset — but promoting them would still have deleted the lost fields.
    #[test]
    fn a_record_that_lost_fields_and_changed_one_is_still_behind() {
        let rich = json!({ "id": "x.rs", "code": "fn x() {}", "vizCode": "({})", "summary": "long form" });
        let thin = json!({ "id": "x.rs", "code": "fn x() {}", "summary": "short" });
        assert_eq!(
            verdict_for(std::slice::from_ref(&thin), std::slice::from_ref(&rich), "x.rs"),
            Verdict::RuntimeBehind,
        );
    }

    fn an_edge() -> Value {
        json!({
            "id": "a--b", "members": ["a.rs", "b.rs"], "src": "crates/k/tests/t.rs",
            "tests": [{ "name": "t.rs", "src": "#[test]\nfn t() {}\n" }],
        })
    }

    /// THE ONE THAT MUST FAIL AGAINST THE OBVIOUS IMPLEMENTATION.
    ///
    /// `promote` already had a projection per target and the tempting move was to reuse it for edges.
    /// [`seed_content_of`] keeps [`SEED_FIELDS`], which has no `members` — so an edge promoted through
    /// it arrives spanning NOTHING. `set_edge` refuses fewer than two members, but that guard is on the
    /// WRITE; a store loaded from such a file reads as a covered relationship over an empty list, which
    /// is the dangling-edge failure the tier exists to make visible.
    #[test]
    fn the_edge_projection_keeps_members_where_the_seed_projection_would_drop_them() {
        let e = an_edge();
        assert!(
            seed_content_of(&e).get("members").is_none(),
            "if the seed projection ever gains `members` this guard is inert — check SEED_FIELDS",
        );
        let got = edge_content_of(&e);
        for k in EDGE_FIELDS {
            assert!(got.get(*k).is_some(), "the edge projection dropped `{k}`");
        }
        assert_eq!(got.get("members").and_then(Value::as_array).map(Vec::len), Some(2));
        // And nothing beyond the declared four rides along.
        assert_eq!(got.as_object().map(serde_json::Map::len), Some(EDGE_FIELDS.len()));
    }

    #[test]
    fn promote_adopts_a_new_edge_into_a_store_that_had_none() {
        let repo = empty();
        assert!(repo.get("edges").is_none(), "the empty store carries no edges key");
        let (next, missing, refused) =
            promote_edges_into(&repo, std::slice::from_ref(&an_edge()), &["a--b".to_string()]);
        assert!(missing.is_empty() && refused.is_empty());
        assert_eq!(tracked_edge_ids(&next), vec!["a--b".to_string()]);
        let got = &edges_of(&next)[0];
        assert_eq!(got.get("members").and_then(Value::as_array).map(Vec::len), Some(2));
        assert!(got.get("tests").is_some(), "the carried test travels with the edge");
    }

    /// ADDITIVE, exactly as `set_edge` and `edges_of` are. A promote that names no edge must leave a
    /// store WITHOUT an `edges` key — otherwise every committed store gains `"edges": []` the first
    /// time anyone promotes anything, which is a diff on a file nobody meant to change.
    #[test]
    fn a_promote_naming_no_edge_does_not_insert_an_empty_edges_array() {
        let (next, _, _) = promote_edges_into(&empty(), &[], &[]);
        assert!(next.get("edges").is_none(), "an edgeless promote invented an `edges` key");
        // But a store that ALREADY has the key keeps it, empty or not.
        let with = json!({ "implementations": [], "edges": [] });
        let (kept, _, _) = promote_edges_into(&with, &[], &[]);
        assert!(kept.get("edges").is_some());
    }

    #[test]
    fn promoting_an_edge_never_drops_a_field_the_committed_copy_carries() {
        let repo = json!({ "implementations": [], "edges": [an_edge()] });
        let mut thin = an_edge();
        thin.as_object_mut().unwrap().remove("tests");
        let (next, missing, refused) =
            promote_edges_into(&repo, std::slice::from_ref(&thin), &["a--b".to_string()]);
        assert!(missing.is_empty());
        assert_eq!(refused, vec!["a--b".to_string()], "a regressed upstream edge is refused, not written");
        assert!(edges_of(&next)[0].get("tests").is_some(), "the committed test survived the refusal");
    }

    #[test]
    fn an_edge_absent_upstream_is_reported_rather_than_dropped() {
        let repo = json!({ "implementations": [], "edges": [an_edge()] });
        let (next, missing, _) = promote_edges_into(&repo, &[], &["a--b".to_string()]);
        assert_eq!(missing, vec!["a--b".to_string()]);
        assert_eq!(tracked_edge_ids(&next), vec!["a--b".to_string()], "the committed edge is left alone");
    }
